macro_rules! Stream {
    () => {
        # [doc = " A stream of values produced asynchronously."] # [doc = ""] # [doc = " If `Future<Output = T>` is an asynchronous version of `T`, then `Stream<Item"] # [doc = " = T>` is an asynchronous version of `Iterator<Item = T>`. A stream"] # [doc = " represents a sequence of value-producing events that occur asynchronously to"] # [doc = " the caller."] # [doc = ""] # [doc = " The trait is modeled after `Future`, but allows `poll_next` to be called"] # [doc = " even after a value has been produced, yielding `None` once the stream has"] # [doc = " been fully exhausted."] # [must_use = "streams do nothing unless polled"] pub trait Stream { # [doc = " Values yielded by the stream."] type Item ; # [doc = " Attempt to pull out the next value of this stream, registering the"] # [doc = " current task for wakeup if the value is not yet available, and returning"] # [doc = " `None` if the stream is exhausted."] # [doc = ""] # [doc = " # Return value"] # [doc = ""] # [doc = " There are several possible return values, each indicating a distinct"] # [doc = " stream state:"] # [doc = ""] # [doc = " - `Poll::Pending` means that this stream's next value is not ready"] # [doc = "   yet. Implementations will ensure that the current task will be notified"] # [doc = "   when the next value may be ready."] # [doc = ""] # [doc = " - `Poll::Ready(Some(val))` means that the stream has successfully"] # [doc = "   produced a value, `val`, and may produce further values on subsequent"] # [doc = "   `poll_next` calls."] # [doc = ""] # [doc = " - `Poll::Ready(None)` means that the stream has terminated, and"] # [doc = "   `poll_next` should not be invoked again."] # [doc = ""] # [doc = " # Panics"] # [doc = ""] # [doc = " Once a stream has finished (returned `Ready(None)` from `poll_next`), calling its"] # [doc = " `poll_next` method again may panic, block forever, or cause other kinds of"] # [doc = " problems; the `Stream` trait places no requirements on the effects of"] # [doc = " such a call. However, as the `poll_next` method is not marked `unsafe`,"] # [doc = " Rust's usual rules apply: calls must never cause undefined behavior"] # [doc = " (memory corruption, incorrect use of `unsafe` functions, or the like),"] # [doc = " regardless of the stream's state."] # [doc = ""] # [doc = " If this is difficult to guard against then the [`fuse`] adapter can be used"] # [doc = " to ensure that `poll_next` always returns `Ready(None)` in subsequent"] # [doc = " calls."] # [doc = ""] # [doc = " [`fuse`]: https://docs.rs/futures/0.3/futures/stream/trait.StreamExt.html#method.fuse"] fn poll_next (self : Pin < & mut Self > , cx : & mut Context < '_ >) -> Poll < Option < Self :: Item > > ; # [doc = " Returns the bounds on the remaining length of the stream."] # [doc = ""] # [doc = " Specifically, `size_hint()` returns a tuple where the first element"] # [doc = " is the lower bound, and the second element is the upper bound."] # [doc = ""] # [doc = " The second half of the tuple that is returned is an [`Option`]`<`[`usize`]`>`."] # [doc = " A [`None`] here means that either there is no known upper bound, or the"] # [doc = " upper bound is larger than [`usize`]."] # [doc = ""] # [doc = " # Implementation notes"] # [doc = ""] # [doc = " It is not enforced that a stream implementation yields the declared"] # [doc = " number of elements. A buggy stream may yield less than the lower bound"] # [doc = " or more than the upper bound of elements."] # [doc = ""] # [doc = " `size_hint()` is primarily intended to be used for optimizations such as"] # [doc = " reserving space for the elements of the stream, but must not be"] # [doc = " trusted to e.g., omit bounds checks in unsafe code. An incorrect"] # [doc = " implementation of `size_hint()` should not lead to memory safety"] # [doc = " violations."] # [doc = ""] # [doc = " That said, the implementation should provide a correct estimation,"] # [doc = " because otherwise it would be a violation of the trait's protocol."] # [doc = ""] # [doc = " The default implementation returns `(0, `[`None`]`)` which is correct for any"] # [doc = " stream."] # [inline] fn size_hint (& self) -> (usize , Option < usize >) { (0 , None) } }
    };
}

Stream!()